insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-cold-lead', 'Comercial D1 / D5 / D7 / D60', 'Aquecimento sem disparo automático, com mensagens variadas e registro manual.', 'COLD_LEAD', 'SDR_LEADS', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-not-closed', 'Não fechou — régua da Concierge (D1–D5)', 'Paciente não fechou: a Concierge (Aline) faz 1 contato por dia útil, do D1 ao D5, com carinho e sem cobrança. Qualquer resposta encerra a régua; sem resposta no D5 → Estevão assume (5 ligações).', 'POST_CONSULTATION_NOT_CLOSED', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-concierge-d1', 'Concierge D+1', 'Boas-vindas, acolhimento e pedido de avaliação Google.', 'POST_SALE_CONCIERGE', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-pos-consulta-d1', 'Pós-consulta D+1 (Concierge)', 'Assim que a recepção marca a consulta como REALIZADA, a concierge recebe o D+1 no dia seguinte — a lista de quem passou com o Dr. aparece em Minhas Tarefas, sem caçar no Kanban.', 'POST_SALE_CONCIERGE', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-nursing-14', 'Enfermagem 14 em 14 dias', 'Acompanhamento humano, sem sobrepor contato do mesmo dia.', 'NURSING_14_DAYS', 'ENFERMAGEM', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-post-application', 'Pós-aplicação / bioimpedância', 'Mensagem do dia seguinte no bloco 10h00–10h30 (POP v3 — o horário da tarde foi extinto). Sem resposta → D2–D5 no mesmo bloco; D5 sem resposta → Gestor.', 'POST_APPLICATION_NURSING', 'ENFERMAGEM', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-rescue-60d', 'Resgate tradicional (60 dias) — Aline', 'Paciente sumiu do ciclo de retorno: 5 tentativas em horários diferentes. Resposta pausa a régua; sem resposta vira churn e a Aline liga.', 'RESCUE_60_DAYS', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-rescue-6m', 'Resgate 6 meses — Aline', 'Sumiu há 6 meses: 5 tentativas, conteúdo de valor primeiro, depois a pergunta do porquê não voltou.', 'RESCUE_60_DAYS', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-rescue-1y', 'Resgate 1 ano — Aline', 'Paciente sumiu há cerca de 1 ano: 5 tentativas de reaproximação com propósito. Resposta pausa a régua; sem resposta a Aline liga. (Isto é resgate, não é a mensagem de aniversário.)', 'RESCUE_60_DAYS', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-anniversary-1y', 'Aniversário de 1 ano — Aline', 'Comemoração de 1 ano de Instituto: parabéns, convite ao Instagram e proposta de avaliação de evolução. É celebração, não resgate — enfileira só quem segue ativo/recente.', 'ANNIVERSARY_1Y', 'CONCIERGE', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-pos-fechamento-d2d5', 'Follow-up pós-fechamento D2–D5 (Recepção)', 'Paciente não respondeu ao D+1 do fechamento: a Recepção conduz os follow-ups D2–D5 (POP: máx. 1 cadência ativa por paciente — a pauta mais urgente é agendar). Resposta encerra; sem resposta no D5 → Gestor.', 'POST_SALE_CONCIERGE', 'RECEPCAO', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-gestor-5lig', 'Trilha de resgate do Gestor — 5 ligações (Estevão)', 'Cadência D1–D5 esgotada sem resposta: 5 ligações em dias alternados e horários diferentes. Sem contato na 5ª → mensagem-padrão de encerramento (POP 5.1); o paciente segue para os resgates de 6 meses e 1 ano.', 'COMMERCIAL_FOLLOW_UP', 'ADMIN_GESTAO', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
insert into crm_cadences (client_ref, name, description, cadence_type, default_owner_role, active) values ('cad-gestor-3131', '3·1·3·1 do Gestor (Estevão)', 'Follow-up do gestor: 3 dias, 1 semana, 3 semanas e 1 mês após o gatilho — negociações paradas e recuperações.', 'POST_CONSULTATION_NOT_CLOSED', 'ADMIN_GESTAO', true) on conflict (client_ref) do update set name = excluded.name, description = excluded.description, cadence_type = excluded.cadence_type, default_owner_role = excluded.default_owner_role, active = excluded.active, updated_at = now();
