insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-lead-d1', 'Lead frio D1', 'SDR', 'SDR_LEADS', 'COLD_LEAD', 'WHATSAPP', 'Olá, {{primeiro_nome}}. Aqui é da equipe Bratan. Vi seu interesse em transformação de saúde e queria entender se você busca algo pontual ou uma mudança mais completa.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-lead-d5', 'Lead D5', 'SDR', 'SDR_LEADS', 'COLD_LEAD', 'WHATSAPP', '{{primeiro_nome}}, passando com outro olhar: o que mais tem pesado hoje, energia, composição corporal, sono ou rotina? Posso te orientar o melhor próximo passo.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-lead-d7', 'Lead D7', 'SDR', 'SDR_LEADS', 'COLD_LEAD', 'WHATSAPP', '{{primeiro_nome}}, se fizer sentido, posso te enviar um conteúdo curto do Dr. Daniel explicando como avaliamos longevidade e performance aqui no Instituto.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-lead-d60', 'Lead D60', 'SDR', 'SDR_LEADS', 'COLD_LEAD', 'WHATSAPP', '{{primeiro_nome}}, retomando com cuidado. Ainda faz sentido conversarmos sobre seu plano de saúde e performance neste momento?', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-resgate-60', 'Resgate 60 dias', 'Aline', 'CONCIERGE', 'RESCUE_60_DAYS', 'WHATSAPP', '{{primeiro_nome}}, aqui é a Aline, do Instituto Bratan. Sentimos sua falta no ciclo de retorno! Posso te ajudar a reagendar num horário que encaixe na sua rotina?', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-resgate-6m', 'Resgate 6 meses', 'Aline', 'CONCIERGE', 'RESCUE_60_DAYS', 'WHATSAPP', '{{primeiro_nome}}, aqui é a Aline, do Instituto Bratan. O Dr. Daniel gravou um conteúdo novo que lembrei de você. Como está sua saúde nesses últimos meses? Adoraria te ver por aqui de novo.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-resgate-1a', 'Resgate 1 ano', 'Aline', 'CONCIERGE', 'RESCUE_60_DAYS', 'WHATSAPP', '{{primeiro_nome}}, aqui é a Aline, do Instituto Bratan. Faz quase um ano que não nos falamos e você não saiu do meu radar. Como está sua saúde hoje? Adoraria retomar seu acompanhamento com a gente.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-aniversario-1a', 'Aniversário 1 ano', 'Aline', 'CONCIERGE', 'ANNIVERSARY_1Y', 'WHATSAPP', '{{primeiro_nome}}, hoje faz 1 ano que você chegou ao Instituto Bratan — parabéns por ter cuidado de você! Segue nosso Instagram para acompanhar as novidades. Que tal marcarmos uma avaliação para ver sua evolução?', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-aniversario-1a-2', 'Aniversário 1 ano - reforço', 'Aline', 'CONCIERGE', 'ANNIVERSARY_1Y', 'WHATSAPP', '{{primeiro_nome}}, reforçando o convite: montar uma avaliação de evolução dos seus 12 meses seria lindo de ver juntos. Quando encaixa na sua semana?', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-pos-consulta-d1', 'Pós-consulta D+1 (Concierge)', 'Aline', 'CONCIERGE', 'POST_SALE_CONCIERGE', 'WHATSAPP', 'Oi, {{primeiro_nome}}! Aqui é a Aline, do Instituto Bratan. 🌿 Que bom ter você com a gente ontem na consulta com o Dr. Daniel! Passando para saber como você saiu de lá e se ficou alguma dúvida sobre o que foi conversado. Estou por aqui para o que precisar.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-pos-consulta-d3', 'Pós-consulta D+3 (Concierge)', 'Aline', 'CONCIERGE', 'POST_SALE_CONCIERGE', 'WHATSAPP', '{{primeiro_nome}}, tudo bem? Só passando de novo para saber como você está pensando sobre o seu plano de cuidado. Qualquer dúvida para dar o próximo passo, é só me chamar por aqui. 😊', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-followup-d2', 'Follow-up D2 (POP 5.3)', 'Recepção', 'RECEPCAO', 'POST_SALE_CONCIERGE', 'WHATSAPP', 'Oi, {{primeiro_nome}}! Passando para saber se você viu a minha mensagem de ontem. Qualquer coisa, estou por aqui. 🌿', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-followup-d3', 'Follow-up D3 (POP 5.3)', 'Recepção', 'RECEPCAO', 'POST_SALE_CONCIERGE', 'WHATSAPP', '{{primeiro_nome}}, tudo bem por aí? Sigo à disposição para agendar suas consultas. É só me responder por aqui!', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-followup-d4', 'Follow-up D4 (POP 5.3)', 'Recepção', 'RECEPCAO', 'POST_SALE_CONCIERGE', 'WHATSAPP', 'Oi, {{primeiro_nome}}! Para facilitar, posso te ligar? Me diz o melhor horário que eu te ligo rapidinho. 😊', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-followup-d5', 'Follow-up D5 (POP 5.3)', 'Recepção', 'RECEPCAO', 'POST_SALE_CONCIERGE', 'WHATSAPP', '{{primeiro_nome}}, essa é a minha última mensagem por aqui para não te incomodar. Se preferir, nosso coordenador pode te ligar para resolver tudo de uma vez — é só me confirmar. Estamos à disposição!', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-gestor-ligacao', 'Ligação do gestor (roteiro)', 'Gestão', 'ADMIN_GESTAO', 'COMMERCIAL_FOLLOW_UP', 'WHATSAPP', 'LIGAR para {{nome}} (não é mensagem): entender com escuta por que não está respondendo — agendamento, aplicação, concierge ou contrato. Dias alternados, horários diferentes. Registrar data, hora e status na planilha do gestor.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-encerramento-gestor', 'Encerramento do gestor (POP 5.1)', 'Gestão', 'ADMIN_GESTAO', 'COMMERCIAL_FOLLOW_UP', 'WHATSAPP', 'Olá, {{primeiro_nome}}, tudo bem? Aqui é o Estevão, coordenador do Instituto Bratan. 🌿 Nos últimos dias, nossa equipe tentou falar com você por mensagem e eu tentei algumas ligações em dias e horários diferentes, mas infelizmente não conseguimos contato. Por respeito ao seu tempo e ao seu espaço, estou encerrando por aqui as nossas tentativas. Quero que saiba que as portas do Instituto continuam abertas para você: a qualquer momento, é só responder esta mensagem ou ligar para a nossa equipe no 11 91752-3530 que retomamos de onde paramos — seja para agendar, tirar uma dúvida ou dar continuidade ao seu tratamento. Estamos aguardando o seu contato para prestar a você um trabalho de excelência e uma experiência completa na transformação da sua saúde. Um abraço, Estevão · Instituto Bratan.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-gestor-3131', 'Gestor 3·1·3·1', 'Gestão', 'ADMIN_GESTAO', 'POST_CONSULTATION_NOT_CLOSED', 'WHATSAPP', '{{primeiro_nome}}, aqui é o Estevão, gestor do Instituto Bratan. Passando para saber se ficou alguma dúvida e como posso facilitar seu próximo passo com a gente.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-naofechou-d1', 'Não fechou D1 — acolhimento da Concierge', 'Recuperação', 'CONCIERGE', 'POST_CONSULTATION_NOT_CLOSED', 'WHATSAPP', 'Olá, {{primeiro_nome}}, tudo bem? Aqui é a Aline, do Instituto Bratan. 🌿 Foi um prazer receber você na consulta! Sei que é uma decisão importante e queria ficar à disposição: se ficou alguma dúvida sobre o plano, valores ou o caminho do tratamento, me conta por aqui que eu te ajudo com todo carinho — sem pressa e sem compromisso.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-concierge-d1', 'Concierge D+1', 'Concierge', 'CONCIERGE', 'POST_SALE_CONCIERGE', 'WHATSAPP', 'Bom dia, {{primeiro_nome}}. Seja muito bem-vindo ao acompanhamento Bratan! Estou por aqui para qualquer dúvida e para cuidar da sua experiência conosco. Se puder, sua avaliação no Google nos ajuda demais: {{link_google_review}}', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
insert into crm_message_templates (client_ref, name, category, role_owner, cadence_type, channel, body, variables_json, active) values ('tpl-concierge-reenvio', 'Concierge reenvio', 'Concierge', 'CONCIERGE', 'POST_SALE_CONCIERGE', 'WHATSAPP', '{{primeiro_nome}}, reforçando que ficamos à disposição. Quando puder, me diga se está tudo claro para o início do seu plano.', '["nome","primeiro_nome","responsavel","data_consulta","hora_consulta","medico","tratamento","proxima_acao","link_google_review"]', true) on conflict (client_ref) do update set name = excluded.name, body = excluded.body, category = excluded.category, role_owner = excluded.role_owner, cadence_type = excluded.cadence_type, channel = excluded.channel, active = excluded.active;
